sparql:
PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?year ?paper ?paperLabel (COUNT(DISTINCT ?method) AS ?methodCount) WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C27001 .
  ?paper rdfs:label ?paperLabel .
  ?paper orkgp:P29 ?year .
  OPTIONAL {
    { ?contribution orkgp:P56008 ?dc . ?dc orkgp:P1005 ?method . }
    UNION
    { ?contribution orkgp:P15124 ?da . ?da orkgp:P1005 ?method . }
  }
}
GROUP BY ?year ?paper ?paperLabel
ORDER BY ?year ?paperLabel

PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?sectionLabel (COUNT(DISTINCT ?valueLabel) AS ?distinctValues) (COUNT(DISTINCT ?paper) AS ?paperCount) WHERE {
  {
    SELECT ?paper ?sectionLabel ?valueLabel WHERE {
      ?paper orkgp:P31 ?contribution .
      ?contribution a orkgc:C121001 .
      {
        ?contribution orkgp:P181002 ?v .
        ?v rdfs:label ?valueLabel .
        BIND("RE task" AS ?sectionLabel)
      }
      UNION
      {
        ?contribution orkgp:P181003 ?nlpTask .
        ?nlpTask orkgp:P181004 ?v .
        ?v rdfs:label ?valueLabel .
        BIND("NLP task type" AS ?sectionLabel)
      }
      UNION
      {
        ?contribution orkgp:P181003 ?nlpTask .
        ?nlpTask orkgp:P181005 ?v .
        ?v rdfs:label ?valueLabel .
        BIND("NLP task input" AS ?sectionLabel)
      }
      UNION
      {
        ?contribution orkgp:HAS_EVALUATION ?ev .
        ?ev orkgp:P110006 ?v .
        ?v rdfs:label ?valueLabel .
        BIND("Evaluation metric" AS ?sectionLabel)
      }
      UNION
      {
        ?contribution orkgp:HAS_EVALUATION ?ev .
        ?ev orkgp:P181051 ?bc .
        ?bc orkgp:P181052 ?v .
        ?v rdfs:label ?valueLabel .
        BIND("Baseline comparison type" AS ?sectionLabel)
      }
      UNION
      {
        ?contribution orkgp:P181011 ?ds .
        ?ds orkgp:P181022 ?dt .
        ?dt orkgp:P181023 ?v .
        ?v rdfs:label ?valueLabel .
        BIND("NLP data format" AS ?sectionLabel)
      }
      UNION
      {
        ?contribution orkgp:P181031 ?ap .
        ?ap orkgp:P181041 ?aa .
        ?aa orkgp:P181042 ?v .
        ?v rdfs:label ?valueLabel .
        BIND("Intercoder reliability metric" AS ?sectionLabel)
      }
    }
  }
}
GROUP BY ?sectionLabel
ORDER BY ?sectionLabel
